/**
 * LocationProvider 和 LocationCallback 空指针安全测试
 *
 * 测试场景：
 * 1. callback 为 null 时调用 onLocationChanged
 * 2. _lastLocation 为 null 时的行为
 * 3. Location 数据边界情况（0,0 坐标）
 */
class LocationProviderTest {

    /**
     * 测试回调空实现
     */
    class NullCallback : LocationCallback {
        var locationChangedCalled = false
        var errorCalled = false

        override fun onLocationChanged(location: Location) {
            locationChangedCalled = true
        }

        override fun onLocationError(errorCode: Int, errorInfo: String) {
            errorCalled = true
        }
    }

    /**
     * 简单的 Location 实现用于测试
     */
    data class TestLocation(
        override val latitude: Double,
        override val longitude: Double,
        override val accuracy: Float,
        override val speed: Float,
        override val bearing: Float,
        override val timestamp: Long,
        override val locationType: LocationType
    ) : Location

    @Before
    fun setup() {
    }

    /**
     * 测试 1: 空 callback 应该安全处理（不抛异常）
     */
    @Test
    fun `test null callback does not throw`() {
        val provider = TestLocationProvider()
        // Should not throw even with null callback
        try {
            provider.setLocationCallback(null)
            provider.onLocationChangedInternal(TestLocation(
                latitude = 39.9042,
                longitude = 116.4074,
                accuracy = 10f,
                speed = 0f,
                bearing = 0f,
                timestamp = System.currentTimeMillis(),
                locationType = LocationType.GPS
            ))
            // If we get here, no exception was thrown
            assertTrue("Should handle null callback gracefully", true)
        } catch (e: NullPointerException) {
            fail("Should not throw NullPointerException with null callback")
        }
    }

    /**
     * 测试 2: callback 正常调用
     */
    @Test
    fun `test callback receives location`() {
        val provider = TestLocationProvider()
        val callback = NullCallback()

        provider.setLocationCallback(callback)
        provider.onLocationChangedInternal(TestLocation(
            latitude = 39.9042,
            longitude = 116.4074,
            accuracy = 10f,
            speed = 0f,
            bearing = 0f,
            timestamp = System.currentTimeMillis(),
            locationType = LocationType.GPS
        ))

        assertTrue("Callback should have been called", callback.locationChangedCalled)
    }

    /**
     * 测试 3: 无效坐标 (0,0) 应该调用 error 回调
     */
    @Test
    fun `test invalid coordinate calls error callback`() {
        val provider = TestLocationProvider()
        val callback = NullCallback()

        provider.setLocationCallback(callback)
        provider.onLocationChangedInternal(TestLocation(
            latitude = 0.0,
            longitude = 0.0,
            accuracy = 10f,
            speed = 0f,
            bearing = 0f,
            timestamp = System.currentTimeMillis(),
            locationType = LocationType.GPS
        ))

        assertFalse("Should not call locationChanged for invalid coords", callback.locationChangedCalled)
        assertTrue("Should call error callback for invalid coords", callback.errorCalled)
    }

    /**
     * 测试 4: getLastLocation 初始为 null
     */
    @Test
    fun `test getLastLocation returns null initially`() {
        val provider = TestLocationProvider()
        assertNull("Last location should be null initially", provider.getLastLocation())
    }

    /**
     * 测试 5: 位置更新后 getLastLocation 返回最新位置
     */
    @Test
    fun `test getLastLocation returns updated location`() {
        val provider = TestLocationProvider()
        val callback = NullCallback()

        provider.setLocationCallback(callback)
        provider.onLocationChangedInternal(TestLocation(
            latitude = 39.9042,
            longitude = 116.4074,
            accuracy = 10f,
            speed = 0f,
            bearing = 0f,
            timestamp = System.currentTimeMillis(),
            locationType = LocationType.GPS
